// PlannerServiceHandler is an implementation of the memos.api.v1.PlannerService service.
type PlannerServiceHandler interface {
	// ListHabits returns the caller's whole habit pool, in creation order. Which
	// habits are in use on a day is decided by habit versions.
	ListHabits(context.Context, *connect.Request[v1.ListHabitsRequest]) (*connect.Response[v1.ListHabitsResponse], error)
	// CreateHabit adds a habit to the pool, with a colour no habit of the latest
	// version uses. It is in use only once a version includes it.
	CreateHabit(context.Context, *connect.Request[v1.CreateHabitRequest]) (*connect.Response[v1.Habit], error)
	// UpdateHabit renames a habit or changes its colour, on every day at once.
	UpdateHabit(context.Context, *connect.Request[v1.UpdateHabitRequest]) (*connect.Response[v1.Habit], error)
	// ListHabitVersions returns the caller's enabled habit versions, earliest
	// first, and the draft not yet enabled, if any.
	ListHabitVersions(context.Context, *connect.Request[v1.ListHabitVersionsRequest]) (*connect.Response[v1.ListHabitVersionsResponse], error)
	// UpdateHabitDraft writes the caller's habit plan draft, creating it or
	// replacing the one there. A draft does not take effect until enabled.
	UpdateHabitDraft(context.Context, *connect.Request[v1.UpdateHabitDraftRequest]) (*connect.Response[v1.HabitVersion], error)
	// DeleteHabitDraft discards the caller's habit plan draft.
	DeleteHabitDraft(context.Context, *connect.Request[v1.DeleteHabitDraftRequest]) (*connect.Response[emptypb.Empty], error)
	// EnableHabitDraft turns the draft into the version in use from the caller's
	// local date on. A version enabled earlier that day is replaced. Once enabled,
	// a version never changes.
	EnableHabitDraft(context.Context, *connect.Request[v1.EnableHabitDraftRequest]) (*connect.Response[v1.HabitVersion], error)
	// ListPlannerEntries returns everything dated within an inclusive range:
	// check-ins, todos of any status, and notes. Undated todos are not included.
	ListPlannerEntries(context.Context, *connect.Request[v1.ListPlannerEntriesRequest]) (*connect.Response[v1.ListPlannerEntriesResponse], error)
	// GetWeekProgress reports how the caller's habit plan went, week by week:
	// the week containing `date` and, with `weeks`, the weeks before it. Weeks
	// start on the caller's planner setting (week_start_day), so they split the
	// same way as in the app. Each week is measured against one plan, the one in
	// effect on its last day, and a habit's count includes check-ins made by
	// completing habit todos, as the app's "2/3" does.
	//
	// It reports facts only: what was planned, what was checked in, and the
	// week's notes. Whether a week passed is for the caller to judge.
	GetWeekProgress(context.Context, *connect.Request[v1.GetWeekProgressRequest]) (*connect.Response[v1.GetWeekProgressResponse], error)
	// ListOpenTodos returns every active todo, dated or not, ordered by date with
	// undated ones last.
	ListOpenTodos(context.Context, *connect.Request[v1.ListOpenTodosRequest]) (*connect.Response[v1.ListOpenTodosResponse], error)
	// ListTodoTags returns the tags used on the caller's todos, most recently
	// used first, to pick from when tagging a todo.
	ListTodoTags(context.Context, *connect.Request[v1.ListTodoTagsRequest]) (*connect.Response[v1.ListTodoTagsResponse], error)
	// SetCheckIn records a check-in, or replaces the note of an existing one.
	// An archived habit takes no new check-ins.
	//
	// With `workout` set, it also records the workout the check-in stands for,
	// replacing any it had (an empty workout removes it); without, the workout
	// is kept. Calling it again with the same habit, date and content changes
	// nothing, so a caller can retry, and correct a workout by sending it whole.
	//
	// A caller with a personal access token (a bot) checks in as an agent. It
	// can change or remove only check-ins made by an agent; on one made in the
	// app it may only set the workout, and the note stays. If an open habit todo
	// of that habit is due that day, an agent's check-in completes it.
	SetCheckIn(context.Context, *connect.Request[v1.SetCheckInRequest]) (*connect.Response[v1.CheckIn], error)
	// DeleteCheckIn removes a habit's check-in on a day. Removing one that does not
	// exist succeeds. A caller with a personal access token can remove only
	// check-ins made by an agent; removing one that completed a habit todo
	// reopens the todo.
	DeleteCheckIn(context.Context, *connect.Request[v1.DeleteCheckInRequest]) (*connect.Response[emptypb.Empty], error)
	// ListWorkouts returns check-ins that carry a workout, newest first: to see
	// what was lifted last time, how often one trained this month, how weights
	// changed. It reports facts only.
	ListWorkouts(context.Context, *connect.Request[v1.ListWorkoutsRequest]) (*connect.Response[v1.ListWorkoutsResponse], error)
	// GetTodo returns one todo.
	GetTodo(context.Context, *connect.Request[v1.GetTodoRequest]) (*connect.Response[v1.Todo], error)
	// CreateTodo adds an active todo.
	CreateTodo(context.Context, *connect.Request[v1.CreateTodoRequest]) (*connect.Response[v1.Todo], error)
	// UpdateTodo changes the fields named in update_mask. Changing `status` follows
	// the todo rules: closing records the close time and whether the todo was
	// already overdue (which needs local_date); cancelling needs a cancel_reason;
	// reopening clears all three.
	UpdateTodo(context.Context, *connect.Request[v1.UpdateTodoRequest]) (*connect.Response[v1.Todo], error)
	// PostponeTodo moves an active, dated todo to a later date. Unlike changing
	// the date through UpdateTodo (which corrects it), this keeps the original
	// date and counts the postponement.
	PostponeTodo(context.Context, *connect.Request[v1.PostponeTodoRequest]) (*connect.Response[v1.Todo], error)
	// DeleteTodo deletes a todo.
	DeleteTodo(context.Context, *connect.Request[v1.DeleteTodoRequest]) (*connect.Response[emptypb.Empty], error)
	// CreatePlannerNote adds a note to a day.
	CreatePlannerNote(context.Context, *connect.Request[v1.CreatePlannerNoteRequest]) (*connect.Response[v1.PlannerNote], error)
	// UpdatePlannerNote changes the fields named in update_mask.
	UpdatePlannerNote(context.Context, *connect.Request[v1.UpdatePlannerNoteRequest]) (*connect.Response[v1.PlannerNote], error)
	// DeletePlannerNote deletes a note.
	DeletePlannerNote(context.Context, *connect.Request[v1.DeletePlannerNoteRequest]) (*connect.Response[emptypb.Empty], error)
	// GetPlannerSettings returns the caller's planner settings.
	GetPlannerSettings(context.Context, *connect.Request[v1.GetPlannerSettingsRequest]) (*connect.Response[v1.PlannerSettings], error)
	// UpdatePlannerSettings replaces the caller's planner settings.
	UpdatePlannerSettings(context.Context, *connect.Request[v1.UpdatePlannerSettingsRequest]) (*connect.Response[v1.PlannerSettings], error)
	// ImportPlanner writes a whole planner in one transaction: the one-time backfill
	// from calendar blocks. It only runs into an empty planner and fails with
	// FAILED_PRECONDITION when the caller already has any planner data.
	ImportPlanner(context.Context, *connect.Request[v1.ImportPlannerRequest]) (*connect.Response[v1.ImportPlannerResponse], error)
}

